#!/bin/bash
# AI DISCLAIMER: All of the text in this file was generated by AI.
# G018 box5600g: one fastbox window, .8 against .9, via the kit's fb_window.sh, governor performance for its duration.
# The kit's table compares arms named S and E, so here S is .8 (bin/E/monerod, the .8 native build) and E is .9
# (bin/N/monerod). usage: PEER=.. PEER_RPC=.. DD=.. SNAP=.. fbm9_window.sh <outdir> <END> <TIMEOUT> <ROUNDS> <threads: default|N> [<extra>]
# Marker: "FBM_WIN_DONE <rc>" as the last line of <outdir>.fbm.
set -u
K=$HOME/work/fastbox/kit/fastbox-kit; BIN=$HOME/work/fastbox/bin
OUT=$1; END=$2; TO=$3; ROUNDS=$4; T=$5; WX=${6:-}; M=$OUT.fbm
if [ "$T" = default ]; then flag="$WX"; else flag="--max-concurrency $T${WX:+ $WX}"; fi
G0=$(cat /sys/devices/system/cpu/cpu0/cpufreq/scaling_governor)
echo "$(date -u +%FT%TZ) start $OUT threads=$T extra=[$WX] arms S=.8 E=.9 governor $G0; load $(cut -d' ' -f1-3 /proc/loadavg); top CPU: $(ps -eo user,pcpu --sort=-pcpu --no-headers | head -3 | tr -s ' ' | tr '\n' ';')" > $M
sudo -n cpupower -c all frequency-set -g performance > /dev/null 2>&1 && echo "governor performance" >> $M
bash $K/fb_window.sh "$OUT" "$END" "$TO" "$ROUNDS" "S|$BIN/E/monerod|$flag" "E|$BIN/N/monerod|$flag" > $OUT.out 2>&1
rc=$?
sudo -n cpupower -c all frequency-set -g $G0 > /dev/null 2>&1; echo "governor back to $(cat /sys/devices/system/cpu/cpu0/cpufreq/scaling_governor)" >> $M
echo "$(date -u +%FT%TZ) FBM_WIN_DONE $rc" >> $M
